def _lcs(a,b):
    n,m=len(a),len(b)
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1,-1,-1):
        for j in range(m-1,-1,-1):
            dp[i][j]=dp[i+1][j+1]+1 if a[i]==b[j] else max(dp[i+1][j],dp[i][j+1])
    ops=[];i=j=0
    while i<n and j<m:
        if a[i]==b[j]: ops.append(('k',a[i]));i+=1;j+=1
        elif dp[i+1][j]>=dp[i][j+1]: ops.append(('d',a[i]));i+=1
        else: ops.append(('i',b[j]));j+=1
    while i<n: ops.append(('d',a[i]));i+=1
    while j<m: ops.append(('i',b[j]));j+=1
    return ops

def diff_patch(a,b):
    A=a.split("\\n"); B=b.split("\\n")
    ops=_lcs(A,B)
    out=[]
    for kind,val in ops:
        if kind=='k':
            if out and out[-1][0]=='keep': out[-1]=('keep',out[-1][1]+1)
            else: out.append(('keep',1))
        elif kind=='d':
            if out and out[-1][0]=='del': out[-1]=('del',out[-1][1]+1)
            else: out.append(('del',1))
        else:
            if out and out[-1][0]=='ins': out[-1]=('ins',out[-1][1]+[val])
            else: out.append(('ins',[val]))
    # canonical: deletion before insertion at same position
    i=0
    while i+1<len(out):
        if out[i][0]=='ins' and out[i+1][0]=='del':
            out[i],out[i+1]=out[i+1],out[i]
            if i>0: i-=1
            continue
        i+=1
    return out

def apply_patch(a,patch):
    A=a.split("\\n"); out=[]; i=0
    for op in patch:
        if op[0]=='keep':
            if i+op[1]>len(A): raise ValueError("bad patch")
            out+=A[i:i+op[1]]; i+=op[1]
        elif op[0]=='del':
            if i+op[1]>len(A): raise ValueError("bad patch")
            i+=op[1]
        elif op[0]=='ins':
            out+=list(op[1])
        else: raise ValueError("bad op")
    if i!=len(A): raise ValueError("did not consume input")
    return "\\n".join(out)
