import base64, json

def encode_cursor(row, sort):
    key={f: row.get(f) for f,_ in sort}
    raw=json.dumps(key, separators=(",",":"), sort_keys=True).encode()
    return base64.urlsafe_b64encode(raw).decode()

def decode_cursor(c):
    return json.loads(base64.urlsafe_b64decode(c.encode()).decode())

class _K:
    __slots__=("v","desc")
    def __init__(self,v,desc): self.v=v; self.desc=desc
    def _rank(self):
        if self.v is None: return (1,0) if not self.desc else (-1,0)
        return (0,0)
    def __lt__(self,o):
        a,b=self.v,o.v
        if a is None and b is None: return False
        if a is None: return self.desc
        if b is None: return not self.desc
        if a==b: return False
        return (a>b) if self.desc else (a<b)
    def __eq__(self,o): return self.v==o.v

def _key(row,sort): return tuple(_K(row.get(f), d=="desc") for f,d in sort)

def _cmp(k1,k2):
    for a,b in zip(k1,k2):
        if a<b: return -1
        if b<a: return 1
    return 0

def keyset_page(rows,*,sort,after=None,limit=10):
    if limit<=0: raise ValueError("limit must be positive")
    ordered=sorted(rows,key=lambda r:_CmpKey(_key(r,sort)))
    if after is not None:
        ck=_key(decode_cursor(after),sort)
        ordered=[r for r in ordered if _cmp(_key(r,sort),ck)>0]
    page=ordered[:limit]
    more=len(ordered)>limit
    nxt=encode_cursor(page[-1],sort) if (page and more) else None
    return {"items":page,"next":nxt,"has_more":more}

class _CmpKey:
    def __init__(self,k): self.k=k
    def __lt__(self,o): return _cmp(self.k,o.k)<0
